Qnn_ErrorHandle_t probabilityNode(Qnn_GraphHandle_t g,Qnn_OpConfig_t config){auto& c=config.v1;std::string type=c.typeName;if(type.rfind("ForwardScoreScale",0)==0){bool obs=type.find("NoReceipt")==std::string::npos;if(c.numOfInputs!=3||c.numOfOutputs!=2+obs)return 1;for(unsigned j=0;j<5;++j){auto& t=(j<3?c.inputTensors[j]:c.outputTensors[j-3]).v1;if(t.rank!=4||t.dimensions[0]!=1||t.dimensions[1]!=1||t.dimensions[2]!=(j==2?1u:32u)||t.dimensions[3]!=(j==2?1u:32u)||t.dataType!=QNN_DATATYPE_FLOAT_32)return 1;}if(obs&&c.outputTensors[2].v1.dimensions[3]!=4105)return 1;++scaleNodes;return QNN_SUCCESS;}if(type.rfind("ForwardSoftmax",0)==0){bool obs=type.find("NoReceipt")==std::string::npos;if(c.numOfInputs!=2||c.numOfOutputs!=2+obs)return 1;for(unsigned j=0;j<2;++j){auto& t=c.inputTensors[j].v1;if(t.rank!=4||t.dimensions[2]!=32||t.dimensions[3]!=32)return 1;}if(obs&&c.outputTensors[2].v1.dimensions[3]!=8328)return 1;++customSoftmaxNodes;}if(type.rfind("ForwardMaskAdd",0)==0){bool obs=type.find("NoReceipt")==std::string::npos;if(c.numOfInputs!=3||c.numOfOutputs!=2+obs)return 1;for(unsigned j=0;j<3;++j){auto& t=c.inputTensors[j].v1;if(t.rank!=4||t.dimensions[2]!=32||t.dimensions[3]!=32||t.dataType!=QNN_DATATYPE_FLOAT_32)return 1;}if(obs&&c.outputTensors[2].v1.dimensions[3]!=5128)return 1;++maskNodes;}if(type==QNN_OP_SOFTMAX){if(c.numOfParams!=2||c.params[0].scalarParam.uint32Value!=3||c.params[1].scalarParam.floatValue!=1.f)return 1;++softmaxNodes;}return node(g,config);}
int main(){api.graphCreate=create;api.tensorCreateGraphTensor=tensorCreate;api.graphAddNode=probabilityNode;api.graphFinalize=finish;unsigned graphs=0;for(bool cs:{false,true})for(bool cm:{false,true})for(bool obs:{false,true})for(bool tap:{false,true})for(unsigned stage=0;stage<5;++stage){probabilitystudy::Native g("probShape"+std::to_string(graphs++),stage,obs,tap,cm,cs);if(!tap){for(auto id:g.heads)if(g.g.tensors[id].v1.type!=QNN_TENSOR_TYPE_NATIVE)return 2;for(auto id:g.raw)if(g.g.tensors[id].v1.type!=QNN_TENSOR_TYPE_NATIVE)return 2;if(stage>=3)for(auto id:g.t.p)if(g.g.tensors[id].v1.type!=QNN_TENSOR_TYPE_NATIVE)return 3;}if(!obs)for(auto t:g.g.tensors)if(t.v1.dataType==QNN_DATATYPE_INT_32)return 4;}
 if(graphs!=80||scaleNodes!=80||softmaxNodes!=48||maskNodes!=32||customSoftmaxNodes!=24)return 5;std::printf("probability_graph_host=PASS graphs=%u scale_nodes=%u softmax_nodes=%u native_saved_p=1 axis=3 beta=1 no_receipt_no_int=1\n",graphs,scaleNodes,softmaxNodes);
}
